// ILLUSTRATIVE ONLY - requires react-router-dom
// import { Navigate, Outlet, useLocation } from 'react-router-dom';

function RequireAuth({ isLoggedIn }) {
  const location = useLocation();
  if (!isLoggedIn) {
    // return so React actually renders the redirect; replace avoids polluting history;
    // pass state so login can send the user back where they came from.
    return <Navigate to="/login" replace state={{ from: location }} />;
  }
  return <Outlet />;
}

function useHashRoute() {
  const [path, setPath] = useState(() => window.location.hash.slice(1) || '/');
  useEffect(() => {
    const onChange = () => setPath(window.location.hash.slice(1) || '/');
    window.addEventListener('hashchange', onChange);
    return () => window.removeEventListener('hashchange', onChange);
  }, []);
  return path;
}

function App() {
  const path = useHashRoute();
  const go = (to) => () => { window.location.hash = to; };
  let view;
  if (path === '/') view = <h2>Home</h2>;
  else if (path.startsWith('/users/')) {
    const id = path.split('/')[2];        // dynamic param
    view = <h2>User #{id}</h2>;
  } else view = <h2>404</h2>;
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={go('/')}>Home</button>
      <button onClick={go('/users/9')} style={{ marginLeft: 8 }}>User 9</button>
      {view}
    </div>
  );
}
